ALTER TABLE public.pharmacies ADD COLUMN habitual_hours text, ADD COLUMN information_source text, ADD COLUMN checked_at timestamptz, ADD COLUMN validation_status text NOT NULL DEFAULT 'unverified', ADD COLUMN commune text, ADD COLUMN region text, ADD COLUMN department text;
UPDATE public.pharmacies SET habitual_hours=opening_hours,information_source=source WHERE duty_publication IS NULL;
UPDATE public.pharmacies p SET region=d.region,department=d.department FROM public.pharmacy_departments d WHERE extensions.ST_Covers(d.boundary,extensions.ST_SetSRID(extensions.ST_MakePoint(p.lng,p.lat),4326));
COMMENT ON COLUMN public.pharmacies.opening_hours IS 'DEPRECATED: habitual_hours is the permanent opening schedule; duty schedules belong in duty_rotations. Legacy field retained without destructive changes.';
CREATE TABLE public.pharmacy_directory_candidates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), evidence_key text NOT NULL UNIQUE, pharmacy_id uuid REFERENCES public.pharmacies(id), name text NOT NULL,address text,city text,commune text,locality text,region text,department text,phone text,habitual_hours text,source text NOT NULL,source_url text,checked_at timestamptz,validation_status text NOT NULL DEFAULT 'unverified',note text,lat double precision,lng double precision);
GRANT SELECT ON public.pharmacy_directory_candidates TO authenticated; GRANT ALL ON public.pharmacy_directory_candidates TO service_role;
ALTER TABLE public.pharmacy_directory_candidates ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins read directory evidence" ON public.pharmacy_directory_candidates FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.duty_rotations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),evidence_key text NOT NULL UNIQUE,pharmacy_id uuid NOT NULL REFERENCES public.pharmacies(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,duty_hours text,published_hours text,source text NOT NULL,source_url text,checked_at timestamptz,validation_status text NOT NULL DEFAULT 'unverified' CHECK(validation_status IN ('unverified','source_checked','validated','cancelled')),note text, CHECK(ends_at>starts_at));
GRANT SELECT ON public.duty_rotations TO anon,authenticated; GRANT ALL ON public.duty_rotations TO service_role;
ALTER TABLE public.duty_rotations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public published rotations" ON public.duty_rotations FOR SELECT TO anon,authenticated USING(validation_status IN ('source_checked','validated') OR (auth.uid() IS NOT NULL AND public.has_role(auth.uid(),'admin')));
CREATE INDEX duty_rotations_dates_idx ON public.duty_rotations(pharmacy_id,starts_at,ends_at);
INSERT INTO public.duty_rotations(evidence_key,pharmacy_id,starts_at,ends_at,published_hours,source,validation_status,note) SELECT 'legacy:'||id||':'||duty_starts_at::text,id,duty_starts_at,on_duty_until,opening_hours,duty_publication,'source_checked','Liste fournie dans la conversation ; non confirmée SPPS/ARP. Horaires publiés non qualifiés comme horaires de garde.' FROM public.pharmacies WHERE duty_starts_at IS NOT NULL AND on_duty_until>duty_starts_at AND duty_publication IS NOT NULL;
CREATE FUNCTION public.pharmacy_duty_at(p_id uuid,p_at timestamptz DEFAULT now()) RETURNS TABLE(id uuid,starts_at timestamptz,ends_at timestamptz,duty_hours text,published_hours text,source text,source_url text,checked_at timestamptz,validation_status text) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT r.id,r.starts_at,r.ends_at,r.duty_hours,r.published_hours,r.source,r.source_url,r.checked_at,r.validation_status FROM public.duty_rotations r WHERE r.pharmacy_id=p_id AND r.validation_status IN ('source_checked','validated') AND r.starts_at<=p_at AND r.ends_at>p_at ORDER BY r.starts_at DESC,r.checked_at DESC NULLS LAST LIMIT 1 $$;
GRANT EXECUTE ON FUNCTION public.pharmacy_duty_at(uuid,timestamptz) TO anon,authenticated,service_role;
CREATE FUNCTION public.search_pharmacy_directory(p_lat double precision,p_lng double precision,p_search text DEFAULT NULL,p_max_km double precision DEFAULT NULL,p_on_duty boolean DEFAULT false,p_with_phone boolean DEFAULT false,p_limit integer DEFAULT 40,p_region text DEFAULT NULL,p_department text DEFAULT NULL,p_city text DEFAULT NULL,p_at timestamptz DEFAULT now(),p_offset integer DEFAULT 0)
RETURNS TABLE(id uuid,name text,address text,locality text,city text,phone text,opening_hours text,lat double precision,lng double precision,on_duty boolean,on_duty_until timestamptz,distance_km double precision)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$
SELECT p.id,p.name,p.address,p.locality,p.city,p.phone,p.habitual_hours,p.lat,p.lng,(r.id IS NOT NULL),r.ends_at,public.distance_km(p_lat,p_lng,p.lat,p.lng)
FROM public.pharmacies p LEFT JOIN LATERAL public.pharmacy_duty_at(p.id,p_at) r ON true
WHERE (NULLIF(btrim(p_search),'') IS NULL OR concat_ws(' ',p.name,p.address,p.locality,p.commune,p.city) ILIKE '%'||p_search||'%')
AND (p_max_km IS NULL OR public.distance_km(p_lat,p_lng,p.lat,p.lng)<=p_max_km)
AND (NOT p_on_duty OR r.id IS NOT NULL) AND (NOT p_with_phone OR NULLIF(btrim(p.phone),'') IS NOT NULL)
AND (NULLIF(p_city,'') IS NULL OR btrim(p.city)=p_city)
AND ((NULLIF(p_region,'') IS NULL AND NULLIF(p_department,'') IS NULL) OR EXISTS(SELECT 1 FROM public.pharmacy_departments d WHERE (NULLIF(p_region,'') IS NULL OR d.region=p_region) AND (NULLIF(p_department,'') IS NULL OR d.department=p_department) AND extensions.ST_Covers(d.boundary,extensions.ST_SetSRID(extensions.ST_MakePoint(p.lng,p.lat),4326))))
ORDER BY public.distance_km(p_lat,p_lng,p.lat,p.lng),p.id LIMIT LEAST(GREATEST(p_limit,1),200) OFFSET GREATEST(p_offset,0) $$;
GRANT EXECUTE ON FUNCTION public.search_pharmacy_directory(double precision,double precision,text,double precision,boolean,boolean,integer,text,text,text,timestamptz,integer) TO anon,authenticated,service_role;
CREATE FUNCTION public.admin_save_directory(p_id uuid,p_data jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result_id uuid; BEGIN
IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Accès réservé aux administrateurs'; END IF;
IF NULLIF(btrim(p_data->>'name'),'') IS NULL THEN RAISE EXCEPTION 'Nom requis'; END IF;
IF NULLIF(btrim(p_data->>'phone'),'') IS NOT NULL AND p_data->>'phone' !~ '^\+221[0-9]{9}$' THEN RAISE EXCEPTION 'Numéro Sénégal attendu'; END IF;
IF (p_data->>'lat')::double precision NOT BETWEEN -90 AND 90 OR (p_data->>'lng')::double precision NOT BETWEEN -180 AND 180 OR p_data->>'lat' IS NULL OR p_data->>'lng' IS NULL THEN RAISE EXCEPTION 'Coordonnées GPS exactes requises'; END IF;
IF p_data->>'validation_status' NOT IN ('unverified','source_checked','validated') THEN RAISE EXCEPTION 'Statut invalide'; END IF;
IF p_data->>'validation_status' IN ('source_checked','validated') AND NULLIF(btrim(p_data->>'information_source'),'') IS NULL THEN RAISE EXCEPTION 'Source requise'; END IF;
IF p_id IS NULL AND EXISTS(SELECT 1 FROM public.pharmacies WHERE lower(btrim(name))=lower(btrim(p_data->>'name')) AND lower(COALESCE(city,''))=lower(COALESCE(p_data->>'city',''))) THEN RAISE EXCEPTION 'Pharmacie déjà enregistrée'; END IF;
IF p_id IS NULL THEN INSERT INTO public.pharmacies(name,lat,lng,source) VALUES(btrim(p_data->>'name'),(p_data->>'lat')::double precision,(p_data->>'lng')::double precision,'user_directory') RETURNING id INTO result_id; ELSE result_id=p_id; END IF;
UPDATE public.pharmacies SET name=btrim(p_data->>'name'),address=NULLIF(btrim(p_data->>'address'),''),city=NULLIF(btrim(p_data->>'city'),''),locality=NULLIF(btrim(p_data->>'locality'),''),commune=NULLIF(btrim(p_data->>'commune'),''),region=NULLIF(btrim(p_data->>'region'),''),department=NULLIF(btrim(p_data->>'department'),''),phone=NULLIF(btrim(p_data->>'phone'),''),habitual_hours=NULLIF(btrim(p_data->>'habitual_hours'),''),information_source=NULLIF(btrim(p_data->>'information_source'),''),validation_status=p_data->>'validation_status',checked_at=CASE WHEN p_data->>'validation_status' IN ('source_checked','validated') THEN now() ELSE NULL END,lat=(p_data->>'lat')::double precision,lng=(p_data->>'lng')::double precision WHERE id=result_id;
IF NOT FOUND THEN RAISE EXCEPTION 'Pharmacie introuvable'; END IF; RETURN result_id; END $$;
REVOKE ALL ON FUNCTION public.admin_save_directory(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_save_directory(uuid,jsonb) TO authenticated;
CREATE FUNCTION public.admin_save_rotation(p_id uuid,p_pharmacy_id uuid,p_starts_at timestamptz,p_ends_at timestamptz,p_duty_hours text,p_source text,p_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Accès réservé aux administrateurs'; END IF;
IF p_starts_at IS NULL OR p_ends_at IS NULL OR p_ends_at<=p_starts_at OR NULLIF(btrim(p_source),'') IS NULL OR p_status NOT IN ('source_checked','validated','cancelled') THEN RAISE EXCEPTION 'Source et période valides requises'; END IF;
IF p_id IS NULL THEN INSERT INTO public.duty_rotations(evidence_key,pharmacy_id,starts_at,ends_at,duty_hours,source,checked_at,validation_status) VALUES('admin:'||gen_random_uuid(),p_pharmacy_id,p_starts_at,p_ends_at,NULLIF(btrim(p_duty_hours),''),btrim(p_source),now(),p_status); ELSE UPDATE public.duty_rotations SET starts_at=p_starts_at,ends_at=p_ends_at,duty_hours=NULLIF(btrim(p_duty_hours),''),source=btrim(p_source),checked_at=now(),validation_status=p_status WHERE id=p_id AND pharmacy_id=p_pharmacy_id; IF NOT FOUND THEN RAISE EXCEPTION 'Rotation introuvable'; END IF; END IF; END $$;
REVOKE ALL ON FUNCTION public.admin_save_rotation(uuid,uuid,timestamptz,timestamptz,text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_save_rotation(uuid,uuid,timestamptz,timestamptz,text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_update_pharmacy(p_id uuid,p_phone text DEFAULT NULL,p_opening_hours text DEFAULT NULL,p_on_duty boolean DEFAULT NULL,p_publication text DEFAULT NULL,p_starts_at timestamptz DEFAULT NULL,p_until timestamptz DEFAULT NULL,p_update_contact boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Accès réservé aux administrateurs'; END IF;
IF p_update_contact AND NULLIF(btrim(p_phone),'') IS NOT NULL AND p_phone !~ '^\+221[0-9]{9}$' THEN RAISE EXCEPTION 'Numéro Sénégal attendu'; END IF;
IF p_on_duty IS TRUE AND (NULLIF(btrim(p_publication),'') IS NULL OR p_starts_at IS NULL OR p_until IS NULL OR p_starts_at>now() OR p_until<=now() OR p_until<=p_starts_at) THEN RAISE EXCEPTION 'Publication et période actuelles requises'; END IF;
UPDATE public.pharmacies SET phone=CASE WHEN p_update_contact THEN NULLIF(btrim(p_phone),'') ELSE phone END,habitual_hours=CASE WHEN p_update_contact THEN NULLIF(btrim(p_opening_hours),'') ELSE habitual_hours END WHERE id=p_id;
IF NOT FOUND THEN RAISE EXCEPTION 'Pharmacie introuvable'; END IF;
IF p_on_duty IS TRUE THEN PERFORM public.admin_save_rotation(NULL,p_id,p_starts_at,p_until,NULL,p_publication,'validated'); ELSIF p_on_duty IS FALSE THEN UPDATE public.duty_rotations SET validation_status='cancelled' WHERE pharmacy_id=p_id AND starts_at<=now() AND ends_at>now(); END IF;
END $$;